import{_ as r,I as t,g as o,j as l}from"./chunks/framework.Ha9mtr6N.js";const c=JSON.parse('{"title":"Общая информация о пространствах","description":"Какие типы рабочих пространств существуют в ОмниКрафт ЕРП, их особенности, реализованные и планируемые модули.","frontmatter":{"title":"Общая информация о пространствах","description":"Какие типы рабочих пространств существуют в ОмниКрафт ЕРП, их особенности, реализованные и планируемые модули.","order":5},"headers":[],"relativePath":"ru/docs/spaces/general.md","filePath":"ru/docs/spaces/general.md"}'),e={name:"ru/docs/spaces/general.md"};function s(i,a,n,g,h,d){return t(),o("div",null,[...a[0]||(a[0]=[l('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🗂️-рабочие-пространства-общая-информация" tabindex="-1">🗂️ Рабочие пространства: Общая информация <a class="header-anchor" href="#🗂️-рабочие-пространства-общая-информация" aria-label="Permalink to &quot;🗂️ Рабочие пространства: Общая информация&quot;">​</a></h1><p>В основе архитектуры <strong>ОмниКрафт ЕРП</strong> лежит концепция изолированных рабочих пространств. Ремесленник, предприниматель или любой человек в своей жизни редко ограничивается одним направлением деятельности. Попытка уместить разнородную деятельность в рамках одной учетной книги неизбежно приводит к искажениям учёта, путанице на складе и неразберихе в аналитике.</p><p>Смешивать всё это в одной куче — значит разрушить экономику каждого отдельного проекта. В ОмниКрафт ЕРП вы можете создавать независимые пространства под каждую задачу, мгновенно переключаясь между ними через выдвижную боковую панель (Drawer).</p><hr><h2 id="🏗️-типы-пространств-и-практические-примеры" tabindex="-1">🏗️ Типы пространств и практические примеры <a class="header-anchor" href="#🏗️-типы-пространств-и-практические-примеры" aria-label="Permalink to &quot;🏗️ Типы пространств и практические примеры&quot;">​</a></h2><p>Вы можете выбрать наиболее подходящий шаблон в зависимости от специфики вашей деятельности:</p><h3 id="🔨-1-производство-уже-реализовано" tabindex="-1">🔨 1. Производство (уже реализовано) <a class="header-anchor" href="#🔨-1-производство-уже-реализовано" aria-label="Permalink to &quot;🔨 1. Производство (уже реализовано)&quot;">​</a></h3><p>Это пространство предназначено для классического ремесленного или любого подходящего производственного цикла, где физическое сырье проходит через стадию обработки и сборки.</p><ul><li><strong>Пример:</strong> Мастерская по пошиву кожаных сумок и аксессуаров.</li><li><strong>Как это работает:</strong> Вы закупаете материалы (склад сырья), создаете технологические карты (калькулятор рецептов), планируете заказы (верстак), зачисляете готовые товары на склад готовой продукции и проводите розничные или оптовые продажи.</li></ul><h3 id="💼-2-услуги-ожидается-скоро" tabindex="-1">💼 2. Услуги (ожидается скоро) <a class="header-anchor" href="#💼-2-услуги-ожидается-скоро" aria-label="Permalink to &quot;💼 2. Услуги (ожидается скоро)&quot;">​</a></h3><p>Шаблон для направлений, связанных с выполнением работ, ремонтом, консультированием или фрилансом, где нет необходимости вести учет серийного производства.</p><ul><li><strong>Пример:</strong> Ремонт и реставрация изделий, частное консультирование, дизайн на заказ или фриланс-услуги.</li><li><strong>Как это работает:</strong> Основной упор здесь делается на учет времени, потраченного на оказание услуги, и фиксацию оплат от клиентов. Склад готовой продукции в данном шаблоне отсутствует за ненадобностью, так как вы продаете свой труд и навыки, а не типовые товары с витрины.</li></ul><h3 id="🛒-3-торговля-ритеил-ожидается-скоро" tabindex="-1">🛒 3. Торговля / Ритейл (ожидается скоро) <a class="header-anchor" href="#🛒-3-торговля-ритеил-ожидается-скоро" aria-label="Permalink to &quot;🛒 3. Торговля / Ритейл (ожидается скоро)&quot;">​</a></h3><p>Вариант для направлений, исключающих производственную фазу.</p><ul><li><strong>Пример:</strong> Продажа сопутствующих товаров, например, инструментов для кожевенников, химии или фурнитуры.</li><li><strong>Как это работает:</strong> Вы закупаете готовые товары оптом, приходуете их непосредственно на витрину и реализуете с наценкой. Цепочка сборки изделий здесь исключена, настраивая интерфейс под чистые торговые операции.</li></ul><h3 id="🌐-4-обучение-digital-ожидается-скоро" tabindex="-1">🌐 4. Обучение / Digital (ожидается скоро) <a class="header-anchor" href="#🌐-4-обучение-digital-ожидается-скоро" aria-label="Permalink to &quot;🌐 4. Обучение / Digital (ожидается скоро)&quot;">​</a></h3><p>Пространство для продажи цифровых продуктов, где себестоимость копирования стремится к нулю.</p><ul><li><strong>Пример:</strong> Продажа авторских PDF-выкроек, лекал, видеоуроков или проведение живых мастер-классов.</li><li><strong>Как это работает:</strong> Вы не списываете физические материалы при каждой продаже. Учет ориентирован на фиксацию прибыли от дистрибуции контента и анализ эффективности каналов привлечения клиентов.</li></ul><h3 id="🌱-5-деятельность-хобби-ожидается-скоро" tabindex="-1">🌱 5. Деятельность / Хобби (ожидается скоро) <a class="header-anchor" href="#🌱-5-деятельность-хобби-ожидается-скоро" aria-label="Permalink to &quot;🌱 5. Деятельность / Хобби (ожидается скоро)&quot;">​</a></h3><p>Песочница для некоммерческих увлечений или проектов на стадии зарождения.</p><ul><li><strong>Пример:</strong> Любительское увлечение керамикой, домашнее пивоварение или садоводство.</li><li><strong>Как это работает:</strong> Вы просто фиксируете расходы на покупку материалов и оборудования, чтобы понимать, во сколько вам обходится увлечение.</li></ul><div class="tip custom-block"><p class="custom-block-title">Плавный переход в бизнес</p><p>Если ваше хобби начинает приносить доход, пространство «Деятельность / Хобби» можно в любой момент бесшовно перевести в статус коммерческого (например, «Производство» или «Услуги»), сохранив всю накопленную историю закупок и базу рецептов.</p></div><h3 id="🏦-6-личное-ожидается-скоро" tabindex="-1">🏦 6. Личное (ожидается скоро) <a class="header-anchor" href="#🏦-6-личное-ожидается-скоро" aria-label="Permalink to &quot;🏦 6. Личное (ожидается скоро)&quot;">​</a></h3><p>Пространство для ведения учёта личных активов, планирования жизни и целеполагания.</p><ul><li><strong>Пример:</strong> Собственная квартира, личный автомобиль, дорогая техника, а также значимые жизненные события (оплата ипотеки, покупка бытовой техники, получение крупного наследства или оплата дорогостоящего обучения).</li><li><strong>Как это работает:</strong> В этом пространстве вы можете эффективно структурировать свою жизнь: намечать ключевые направления деятельности, исходя из ваших желаний и насущных необходимостей, и ставить внутри этих направлений конкретные цели. Цели могут быть как денежными (например, накопить на ремонт или закрыть кредит), так и абсолютно любыми другими (например, пройти обучение или освоить новый навык). Здесь же вы фиксируете свое крупное личное имущество (нефинансовые активы) и отмечаете только значимые разовые приходы и расходы.</li><li><strong>Главное преимущество:</strong> вам больше не нужно вести учет мелких повседневных покупок (продукты, кофе, бензин) — вся подобная рутина уходит в прошлое. Программа в глобальном дашборде <strong>«Мой капитал»</strong> автоматически посчитает все ваши фоновые траты на основе остатков на счетах и картах. Вам достаточно вносить эти остатки с желаемой периодичностью (например, раз в месяц), чтобы наблюдать за ростом или изменением уровня вашего реального богатства в динамике.</li></ul><hr><h2 id="💡-масштабирование-любое-количество-пространств" tabindex="-1">💡 Масштабирование: Любое количество пространств <a class="header-anchor" href="#💡-масштабирование-любое-количество-пространств" aria-label="Permalink to &quot;💡 Масштабирование: Любое количество пространств&quot;">​</a></h2><p>Вы не ограничены рамками «один тип деятельности — одно пространство». Программа позволяет создавать несколько пространств одного типа, если у вас параллельно развивается несколько разных проектов.</p><p>Например, если вы занимаетесь и кожевничеством, и столярным делом, вы можете завести два независимых пространства типа <strong>«Производство»</strong> (например, «Кожаные изделия» и «Деревянная мебель»). А если помимо этого вы занимаетесь реставрацией изделий и берете заказы на графический дизайн, вы можете создать для них отдельные пространства типа <strong>«Услуги»</strong> (например, «Реставрация» и «Фриланс»). Это позволяет полностью разделить их экономику, наценки и складские запасы.</p><hr><h2 id="🏦-консолидация-капитала-модуль-«мои-капитал»-уже-реализовано" tabindex="-1">🏦 Консолидация капитала: Модуль «Мой капитал» (уже реализовано) <a class="header-anchor" href="#🏦-консолидация-капитала-модуль-«мои-капитал»-уже-реализовано" aria-label="Permalink to &quot;🏦 Консолидация капитала: Модуль «Мой капитал» (уже реализовано)&quot;">​</a></h2><p>Несмотря на то, что экономика каждого вашего проекта ведется изолированно, в PRO-режиме ОмниКрафт ЕРП реализован глобальный модуль <strong>«Мой капитал»</strong> (вызывается отдельной кнопкой в боковой панели).</p><p>Этот модуль объединяет показатели всех ваших рабочих пространств и освобождает вас от необходимости вести детальный микроучет мелких повседневных личных трат (на кофе, продукты, бензин и т.д.).</p><h3 id="как-устроен-учет-в-модуле-«мои-капитал»" tabindex="-1">Как устроен учет в модуле «Мой капитал»: <a class="header-anchor" href="#как-устроен-учет-в-модуле-«мои-капитал»" aria-label="Permalink to &quot;Как устроен учет в модуле «Мой капитал»:&quot;">​</a></h3><ol><li><strong>Мои счета:</strong> На этой вкладке вы один раз заводите свои реальные банковские карты, наличные кошельки, вклады или брокерские счета. Вам <strong>не нужно</strong> вносить туда каждую мелкую трату. Вместо этого вы просто периодически (например, раз в месяц) заходите и обновляете фактические остатки на этих счетах.</li><li><strong>Мои активы и значимые операции:</strong> Сюда программа автоматически подтягивает данные из вашего пространства <strong>«Личное»</strong> (стоимость вашего автомобиля, квартиры, а также крупные зафиксированные доходы и расходы).</li><li><strong>Автоматическая консолидация:</strong> Программа складывает остатки на ваших счетах, стоимость материалов на складах, оценку товаров на витринах и стоимость оборудования всех ваших пространств.</li><li><strong>Расчет свободных трат (Delta):</strong> Программа берет совокупную прибыль всей вашей деятельности, прибавляет значимые личные доходы, вычитает значимые расходы и сравнивает это с фактическим ростом денег на ваших личных счетах. На основе этой разницы система сама рассчитывает баланс неучтенных повседневных мелочей — объединяя все ваши мелкие бытовые расходы и небольшие случайные приходы (помимо внесенных вами крупных значимых событий). Это избавляет вас от рутины, наглядно показывая на графиках реальную динамику вашего благосостояния.</li></ol>',36)])])}const u=r(e,[["render",s]]);export{c as __pageData,u as default};
